// P90 - Konfiguration aufloesen
// Prueft die Ressourcenkennung gegen die fest hinterlegte Konfigurationstabelle.
// Zielwerte (Endpunkt, Tabelle, Primaerschluessel, Seitengroesse) kommen
// ausschliesslich aus dieser festen Konfiguration, NICHT aus Aufrufer-Eingaben
// (E-31c, E-31j: keine dynamischen SQL-/Tabellennamen aus Nutzereingaben).

const eingabe = $input.first().json;

function feld(name, fallback) {
  const w = eingabe[name];
  if (w !== undefined && w !== null && w !== '') return w;
  return fallback;
}

const kennung = feld('Ressourcenkennung', feld('ressourcenkennung', feld('kennung', null)));
const runId = feld('Laufkennung', feld('run_id', feld('runId', null)));
const loeschungenEingabe =
  eingabe['Löschungen auswerten'] !== undefined ? eingabe['Löschungen auswerten'] :
  eingabe['Loeschungen auswerten'] !== undefined ? eingabe['Loeschungen auswerten'] :
  eingabe['loeschungen_auswerten'];

// ---------------------------------------------------------------------------
// Feste Konfigurationstabelle.
// ---------------------------------------------------------------------------
const KONFIG = {
  edo_admins: {
    kennung: 'edo_admins',
    endpunkt: '/admin/list',
    schema: 'edoobox_raw',
    zieltabelle: 'trainer_admin',
    pk: 'admin_id',
    seitengroesse: 2000,
    loeschungen: true,
    hash: false,
    payload: false,
    spalten: [
      { ziel: 'admin_id',  quelle: 'id',         typ: 'kennung', sqlTyp: 'text' },
      { ziel: 'shortcut',  quelle: 'shortcut',   typ: 'text',    sqlTyp: 'text' },
      { ziel: 'permission', quelle: 'permission', typ: 'text',   sqlTyp: 'text' },
      { ziel: 'is_active', quelle: 'status',     typ: 'wahr',    sqlTyp: 'boolean' },
    ],
    zusatzSpalten: [],
    userRef: null,
    hashFelder: ['shortcut', 'permission', 'is_active'],
  },

  edo_dates: {
    kennung: 'edo_dates',
    endpunkt: '/date/list',
    schema: 'edoobox_raw',
    zieltabelle: 'offer_date',
    pk: 'date_id',
    seitengroesse: 2000,
    loeschungen: true,
    hash: false,
    payload: false,
    spalten: [
      { ziel: 'date_id',    quelle: 'id',         typ: 'kennung', sqlTyp: 'text' },
      { ziel: 'offer_id',   quelle: 'offer',      typ: 'kennung', sqlTyp: 'text' },
      { ziel: 'date_start', quelle: 'date_start', typ: 'zeitpunkt', sqlTyp: 'timestamptz' },
      { ziel: 'date_end',   quelle: 'date_end',   typ: 'zeitpunkt', sqlTyp: 'timestamptz' },
      { ziel: 'place_ref',  quelle: 'place',      typ: 'kennung', sqlTyp: 'text' },
      { ziel: 'room_ref',   quelle: 'room',       typ: 'kennung', sqlTyp: 'text' },
    ],
    zusatzSpalten: [],
    userRef: null,
    hashFelder: ['offer_id', 'date_start', 'date_end', 'place_ref', 'room_ref'],
  },

  edo_offers: {
    kennung: 'edo_offers',
    endpunkt: '/offer/list',
    schema: 'edoobox_raw',
    zieltabelle: 'offer',
    pk: 'offer_id',
    seitengroesse: 2000,
    loeschungen: true,
    hash: true,
    payload: true,
    spalten: [
      { ziel: 'offer_id',            quelle: 'id',                 typ: 'kennung',   sqlTyp: 'text' },
      { ziel: 'offer_number',        quelle: 'number',             typ: 'text',      sqlTyp: 'text' },
      { ziel: 'name',                quelle: 'name',               typ: 'text',      sqlTyp: 'text' },
      { ziel: 'category_ref',        quelle: 'category',           typ: 'kennung',   sqlTyp: 'text' },
      { ziel: 'offerdef_ref',        quelle: 'offerdef',           typ: 'kennung',   sqlTyp: 'text' },
      { ziel: 'place_ref',           quelle: 'place',              typ: 'kennung',   sqlTyp: 'text' },
      { ziel: 'date_start',          quelle: 'date_start',         typ: 'zeitpunkt', sqlTyp: 'timestamptz' },
      { ziel: 'date_end',            quelle: 'date_end',           typ: 'zeitpunkt', sqlTyp: 'timestamptz' },
      { ziel: 'date_signupstart',    quelle: 'date_signupstart',   typ: 'zeitpunkt', sqlTyp: 'timestamptz' },
      { ziel: 'date_close',          quelle: 'date_close',         typ: 'zeitpunkt', sqlTyp: 'timestamptz' },
      { ziel: 'user_minimal',        quelle: 'user_minimal',       typ: 'ganzzahl',  sqlTyp: 'integer' },
      { ziel: 'user_maximum',        quelle: 'user_maximum',       typ: 'ganzzahl',  sqlTyp: 'integer' },
      { ziel: 'status',              quelle: 'status',             typ: 'text',      sqlTyp: 'text' },
      { ziel: 'mode',                quelle: 'mode',               typ: 'text',      sqlTyp: 'text' },
      { ziel: 'offer_type',          quelle: 'type',               typ: 'text',      sqlTyp: 'text' },
      { ziel: 'vat_rate',            quelle: 'vat',                typ: 'kommazahl', sqlTyp: 'numeric(6,3)' },
      { ziel: 'country',             quelle: 'country',            typ: 'text',      sqlTyp: 'text' },
      { ziel: 'internal_code',       quelle: 'internal_code',      typ: 'text',      sqlTyp: 'text' },
      { ziel: 'is_archived',         quelle: 'archive',            typ: 'wahr',      sqlTyp: 'boolean' },
      { ziel: 'is_trash',            quelle: 'trash',              typ: 'wahr',      sqlTyp: 'boolean' },
      { ziel: 'has_waiting_list',    quelle: 'waiting_list',       typ: 'wahr',      sqlTyp: 'boolean' },
      { ziel: 'mustpay',             quelle: 'mustpay',            typ: 'wahr',      sqlTyp: 'boolean' },
      { ziel: 'is_multi_offer',      quelle: 'multi_offer',        typ: 'wahr',      sqlTyp: 'boolean' },
      { ziel: 'is_multi_offer_child', quelle: 'multi_offer_child', typ: 'wahr',      sqlTyp: 'boolean' },
    ],
    zusatzSpalten: [],
    userRef: null,
    hashFelder: [
      'name', 'offer_number', 'category_ref', 'place_ref',
      'date_start', 'date_end', 'user_minimal', 'user_maximum',
      'status', 'mode', 'offer_type', 'vat_rate', 'is_archived', 'is_trash',
    ],
  },

  edo_bookings: {
    kennung: 'edo_bookings',
    endpunkt: '/booking/list',
    schema: 'edoobox_raw',
    zieltabelle: 'booking',
    pk: 'booking_id',
    seitengroesse: 2000,
    loeschungen: true,
    hash: true,
    payload: false,
    source: 'api',
    spalten: [
      { ziel: 'booking_id',     quelle: 'id',           typ: 'kennung',   sqlTyp: 'text' },
      { ziel: 'offer_id',       quelle: 'offer',        typ: 'kennung',   sqlTyp: 'text' },
      { ziel: 'status',         quelle: 'status',       typ: 'text',      sqlTyp: 'text' },
      { ziel: 'booking_time',   quelle: 'time',         typ: 'zeitpunkt', sqlTyp: 'timestamptz' },
      { ziel: 'is_b2b',         quelle: 'b2b',          typ: 'wahr',      sqlTyp: 'boolean' },
      { ziel: 'is_multi_offer', quelle: 'multi_offer',  typ: 'wahr',      sqlTyp: 'boolean' },
    ],
    zusatzSpalten: [
      { name: 'owner',   quelle: 'owner',   typ: 'text', sqlTyp: 'text' },
      { name: 'mustpay', quelle: 'mustpay', typ: 'wahr', sqlTyp: 'boolean' },
      { name: 'label',   quelle: 'label',   typ: 'text', sqlTyp: 'text' },
    ],
    userRef: { quelle: 'owner', ziel: 'user_ref' },
    hashFelder: ['offer_id', 'status', 'booking_time', 'mustpay', 'label'],
  },

  edo_invoices: {
    kennung: 'edo_invoices',
    endpunkt: '/invoice/list',
    schema: 'edoobox_raw',
    zieltabelle: 'invoice',
    pk: 'invoice_id',
    seitengroesse: 2000,
    loeschungen: true,
    hash: true,
    payload: true,
    spalten: [
      { ziel: 'invoice_id',       quelle: 'id',               typ: 'kennung',      sqlTyp: 'text' },
      { ziel: 'invoice_number',   quelle: 'number',           typ: 'text',         sqlTyp: 'text' },
      { ziel: 'status',           quelle: 'status',           typ: 'ganzzahl',     sqlTyp: 'integer' },
      { ziel: 'status_text',      quelle: 'status',           typ: 'rechnungsstatus', sqlTyp: 'text' },
      { ziel: 'currency',         quelle: 'currency',         typ: 'waehrung',     sqlTyp: 'text' },
      { ziel: 'amount',           quelle: 'amount',           typ: 'kommazahl',    sqlTyp: 'numeric(12,2)' },
      { ziel: 'date_create',      quelle: 'date_create',      typ: 'zeitpunkt',    sqlTyp: 'timestamptz' },
      { ziel: 'date_pay',         quelle: 'date_pay',         typ: 'zeitpunkt',    sqlTyp: 'timestamptz' },
      { ziel: 'date_payuntil',    quelle: 'date_payuntil',    typ: 'zeitpunkt',    sqlTyp: 'timestamptz' },
      { ziel: 'date_cancelled',   quelle: 'date_cancelled',   typ: 'zeitpunkt',    sqlTyp: 'timestamptz' },
      { ziel: 'offer_start_date', quelle: 'offer_start_date', typ: 'zeitpunkt',    sqlTyp: 'timestamptz' },
    ],
    zusatzSpalten: [
      { name: 'user', quelle: 'user', typ: 'text', sqlTyp: 'text' },
    ],
    userRef: { quelle: 'user', ziel: 'user_ref' },
    hashFelder: [
      'invoice_number', 'status', 'status_text', 'currency', 'amount',
      'date_create', 'date_pay', 'date_payuntil', 'date_cancelled', 'offer_start_date',
    ],
  },
};

// Ressourcen ohne Zieltabelle im Workspace (offener Punkt O-2).
const NICHT_SPIEGELBAR = {
  Vat:                 { kennung: 'Vat',                 endpunkt: '/vat/list',            grund: 'keine Zieltabelle im Workspace (O-2)' },
  Countries:           { kennung: 'Countries',           endpunkt: '/country/list',        grund: 'keine Zieltabelle im Workspace (O-2)' },
  edo_categories:      { kennung: 'edo_categories',      endpunkt: '/category/list',       grund: 'keine Zieltabelle im Workspace (O-2)' },
  edo_users:           { kennung: 'edo_users',           endpunkt: '/user/list',           grund: 'keine Zieltabelle; nur md5(user_ref) in booking/invoice (O-2)' },
  edo_pricecategories: { kennung: 'edo_pricecategories', endpunkt: '/pricecategory/list',  grund: 'keine eigenstaendige Zieltabelle; nur booking_position/preiskategorie_ausnahme (O-2)' },
  edo_attendances:     { kennung: 'edo_attendances',     endpunkt: '/attendance/list',     grund: 'keine Zieltabelle; nicht erforderlich fuer DB I (O-2)' },
  edo_transactions:    { kennung: 'edo_transactions',    endpunkt: '/transaction/list',    grund: 'nur Buchungsbezug in booking_transaction; Gesamtressource ohne Zieltabelle (O-2/O-9)' },
};

if (!kennung) {
  throw new Error('P90: Parameter "Ressourcenkennung" fehlt.');
}

if (NICHT_SPIEGELBAR[kennung]) {
  const n = NICHT_SPIEGELBAR[kennung];
  throw new Error('P90: Ressource "' + kennung + '" ist nicht spiegelbar: ' + n.grund);
}

const konfig = KONFIG[kennung];
if (!konfig) {
  throw new Error(
    'P90: Unbekannte Ressourcenkennung "' + kennung + '". Bekannt: ' + Object.keys(KONFIG).join(', ')
  );
}

// Loesch-Auswertung: Der Aufrufer kann den Modus steuern (P01 normal=false,
// P03 voll=true). Ohne explizite Vorgabe gilt der Konfigurationswert.
const loeschungen = typeof loeschungenEingabe === 'boolean' ? loeschungenEingabe : konfig.loeschungen;

return [{
  json: {
    kennung: konfig.kennung,
    endpunkt: konfig.endpunkt,
    zieltabelle: konfig.zieltabelle,
    primaerschluessel: konfig.pk,
    seitengroesse: konfig.seitengroesse,
    loeschungen,
    run_id: runId,
    hash: konfig.hash,
    konfig,
  },
}];

// P90 - Ressource holen
// Seitenweiser Abruf (Paginierung ueber limit[start]/limit[reply]),
// Normalisierung, Hash-Bildung und Erzeugung der parametrisierten UPSERT-Abfrage.
// Tabellen-/Spaltennamen stammen ausschliesslich aus der festen Konfiguration.

const auth = $('P90 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token || !edid) {
  throw new Error('P90: Token oder edid nicht gefunden. Felder: ' + Object.keys(auth).join(', '));
}

const meta = $('P90 Konfiguration aufloesen').first().json;
const k = meta.konfig;
const runId = meta.run_id;
const loeschungen = meta.loeschungen;

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: 'Bearer ' + token,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2';

// ---- Normalisierungs-Helfer (vgl. Schritt 16/26/54) ----
function kennung(w) {
  if (w === null || w === undefined || w === '') return null;
  if (typeof w === 'string' || typeof w === 'number') return String(w);
  if (typeof w === 'object') return w.id ? String(w.id) : null;
  return null;
}
function text(w) {
  if (w === null || w === undefined) return null;
  if (typeof w === 'string') return w;
  if (typeof w === 'number' || typeof w === 'boolean') return String(w);
  return null;
}
function ganzzahl(w) {
  const n = Number(w);
  return Number.isFinite(n) ? Math.trunc(n) : null;
}
function kommazahl(w) {
  if (w === null || w === undefined || w === '') return null;
  const n = Number(String(w).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}
function zeitpunkt(w) {
  if (typeof w !== 'string') return null;
  if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w)) return null;
  if (/^0{4}-0{2}-0{2}/.test(w)) return null;
  return w;
}
function wahr(w) {
  if (w === true || w === 1 || w === '1' || w === 'true') return true;
  if (w === false || w === 0 || w === '0' || w === 'false' || w === '' || w === null || w === undefined) return false;
  return Boolean(w);
}
function rechnungsstatus(w) {
  const n = Number(w);
  return ({ 1: 'offen', 2: 'bezahlt', 3: 'storniert' })[n] ?? null;
}
function waehrung(w) {
  const t = text(w);
  if (!t) return 'EUR';
  return t.toUpperCase().slice(0, 3);
}

function transformiere(typ, w) {
  switch (typ) {
    case 'kennung': return kennung(w);
    case 'text': return text(w);
    case 'ganzzahl': return ganzzahl(w);
    case 'kommazahl': return kommazahl(w);
    case 'zeitpunkt': return zeitpunkt(w);
    case 'wahr': return wahr(w);
    case 'rechnungsstatus': return rechnungsstatus(w);
    case 'waehrung': return waehrung(w);
    default: return text(w);
  }
}

// ---- Paginierung ----
async function holeAlle(pfad, reply) {
  const alle = [];
  let start = 0;
  let total = null;
  let abrufe = 0;
  let letzteErsteId = null;
  const hoechstzahlSeiten = 500; // Schutz gegen Endlosschleifen

  for (let seite = 1; seite <= hoechstzahlSeiten; seite += 1) {
    const a = await this.helpers.httpRequest({
      method: 'GET',
      url: basis + pfad,
      headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true,
      returnFullResponse: true,
      timeout: 120000,
      ignoreHttpStatusErrors: true,
    });
    abrufe += 1;

    if (!(a.statusCode >= 200 && a.statusCode < 300)) {
      throw new Error('P90: ' + pfad + ' lieferte HTTP ' + a.statusCode + ' ab Versatz ' + start);
    }

    const body = a.body;
    const limit = body && body.limit ? body.limit : {};
    if (total === null && limit.total !== undefined && limit.total !== null) {
      total = Number(limit.total);
    }

    const roh = body ? body.data : undefined;
    const eintraege = Array.isArray(roh)
      ? roh
      : (roh && typeof roh === 'object' ? Object.values(roh) : []);

    if (eintraege.length === 0) break;

    // Schutz gegen nicht angenommenen Versatz: wiederholt sich die erste Kennung
    // einer Folgeseite, wird abgebrochen (kein Endlosschleifen, E-31f).
    const ersteId = eintraege[0] && typeof eintraege[0] === 'object' ? String(eintraege[0].id ?? '') : '';
    if (seite > 1 && ersteId !== '' && ersteId === letzteErsteId) {
      throw new Error('P90: ' + pfad + ' nimmt Versatz ab ' + start + ' nicht an (gleiche erste Kennung ' + ersteId + ')');
    }
    letzteErsteId = ersteId;

    alle.push(...eintraege);
    start += eintraege.length;

    if (eintraege.length < reply || (total !== null && start >= total)) break;
  }

  // Vollstaendigkeitsnachweis: gemeldet = gelesen (E-31f).
  if (total !== null && alle.length !== total) {
    throw new Error('P90: ' + pfad + ' meldet ' + total + ' Datensaetze, gelesen ' + alle.length);
  }

  return { alle, total, abrufe };
}

const reply = Math.min(k.seitengroesse || 2000, 2000); // gepruefter Hoechstwert 2000
const { alle, total, abrufe } = await holeAlle(k.endpunkt, reply);

// ---- Normalisierung ----
function normalisiere(satz) {
  const s = satz && typeof satz === 'object' ? satz : {};
  const out = {};
  for (const sp of k.spalten) out[sp.ziel] = transformiere(sp.typ, s[sp.quelle]);
  for (const z of (k.zusatzSpalten || [])) out[z.name] = transformiere(z.typ, s[z.quelle]);
  if (k.payload) out.payload = s;
  return out;
}

const saetze = alle.map(normalisiere);
const datenJson = JSON.stringify(saetze);

// ---- UPSERT-Abfrage generieren ----
function quotIdent(name) {
  return '"' + String(name).replace(/"/g, '""') + '"';
}

const tabelleQualifiziert = quotIdent(k.schema) + '.' + quotIdent(k.zieltabelle);
const pk = k.pk;
const pkQualifiziert = quotIdent(pk);

const recordset = [];
for (const sp of k.spalten) recordset.push(quotIdent(sp.ziel) + ' ' + (sp.sqlTyp || 'text'));
for (const z of (k.zusatzSpalten || [])) recordset.push(quotIdent(z.name) + ' ' + (z.sqlTyp || 'text'));
if (k.payload) recordset.push(quotIdent('payload') + ' jsonb');
const recordsetDef = recordset.join(', ');

const insertSpalten = [];
const insertWerte = [];
for (const sp of k.spalten) {
  insertSpalten.push(quotIdent(sp.ziel));
  insertWerte.push('e.' + quotIdent(sp.ziel));
}
if (k.payload) {
  insertSpalten.push(quotIdent('payload'));
  insertWerte.push('e.' + quotIdent('payload'));
}
if (k.userRef) {
  insertSpalten.push(quotIdent(k.userRef.ziel));
  insertWerte.push('e.' + quotIdent(k.userRef.ziel));
}
if (k.source) {
  insertSpalten.push(quotIdent('source'));
  insertWerte.push("'" + String(k.source).replace(/'/g, "''") + "'");
}

function hashExpr(alias, felder) {
  const teile = felder.map((f) => alias + '.' + quotIdent(f) + '::text');
  return "md5(concat_ws('|', " + teile.join(', ') + '))';
}

// Dollar-Tag so waehlen, dass es nicht im datenJson vorkommt.
let tag = '$p90' + Math.random().toString(36).slice(2, 10) + '$';
while (datenJson.includes(tag)) tag = '$p90' + Math.random().toString(36).slice(2, 10) + '$';
const jsonLiteral = tag + datenJson + tag + '::jsonb';

// Zusaetzlich berechnete Felder im eingang-CTE.
const userRefSelect = k.userRef
  ? ', CASE WHEN t.' + quotIdent(k.userRef.quelle) + ' IS NULL THEN NULL ELSE md5(t.' + quotIdent(k.userRef.quelle) + ') END AS ' + quotIdent(k.userRef.ziel)
  : '';

// Spalten fuer DO UPDATE SET (alle Nicht-PK-Zielspalten + payload + user_ref + source).
const updateSet = [];
for (const sp of k.spalten) {
  if (sp.ziel === pk) continue;
  updateSet.push(quotIdent(sp.ziel) + ' = EXCLUDED.' + quotIdent(sp.ziel));
}
if (k.payload) updateSet.push(quotIdent('payload') + ' = EXCLUDED.' + quotIdent('payload'));
if (k.userRef) updateSet.push(quotIdent(k.userRef.ziel) + ' = EXCLUDED.' + quotIdent(k.userRef.ziel));
if (k.source) updateSet.push(quotIdent('source') + ' = EXCLUDED.' + quotIdent('source'));

let sql = '';

if (k.hash) {
  // Variante mit gespeichertem payload_hash und last_changed_at.
  const hashEingang = hashExpr('t', k.hashFelder);
  const buchInsert = insertSpalten.concat([
    quotIdent('first_seen_at'), quotIdent('last_synced_at'),
    quotIdent('last_changed_at'), quotIdent('payload_hash'), quotIdent('is_deleted'),
  ]).join(', ');
  const buchWerte = insertWerte.concat([
    'now()', 'now()', 'now()', 'e.' + quotIdent('payload_hash'), 'false',
  ]).join(', ');

  sql =
    'WITH eingang AS (\n    SELECT t.*, ' + hashEingang + ' AS ' + quotIdent('payload_hash') + userRefSelect +
    '\n    FROM jsonb_to_recordset(' + jsonLiteral + ') AS t(' + recordsetDef + ')\n),\n' +
    'kennzahlen AS (\n    SELECT\n        count(*) AS zeilen,\n' +
    '        count(*) FILTER (WHERE o.' + pkQualifiziert + ' IS NULL) AS neu,\n' +
    '        count(*) FILTER (WHERE o.' + pkQualifiziert + ' IS NOT NULL AND o.' + quotIdent('payload_hash') + ' IS DISTINCT FROM e.' + quotIdent('payload_hash') + ') AS geaendert\n' +
    '    FROM eingang e\n    LEFT JOIN ' + tabelleQualifiziert + ' o ON o.' + pkQualifiziert + ' = e.' + pkQualifiziert + '\n),\n' +
    'geschrieben AS (\n    INSERT INTO ' + tabelleQualifiziert + ' AS o (' + buchInsert + ')\n' +
    '    SELECT ' + buchWerte + '\n    FROM eingang e\n' +
    '    ON CONFLICT (' + pkQualifiziert + ') DO UPDATE SET\n        ' + updateSet.join(',\n        ') + ',\n' +
    '        ' + quotIdent('last_synced_at') + ' = now(),\n' +
    '        ' + quotIdent('is_deleted') + ' = false,\n' +
    '        ' + quotIdent('last_changed_at') + ' = CASE WHEN o.' + quotIdent('payload_hash') + ' IS DISTINCT FROM EXCLUDED.' + quotIdent('payload_hash') + ' THEN now() ELSE o.' + quotIdent('last_changed_at') + ' END,\n' +
    '        ' + quotIdent('payload_hash') + ' = EXCLUDED.' + quotIdent('payload_hash') + '\n' +
    '    RETURNING o.' + pkQualifiziert + '\n)';
} else {
  // Variante ohne gespeicherten Hash (offer_date, trainer_admin):
  // "geaendert" wird ueber einen On-the-fly-Hashvergleich der bestehenden Zeile bestimmt.
  const hashO = hashExpr('o', k.hashFelder);
  const hashE = hashExpr('e', k.hashFelder);
  const buchInsert = insertSpalten.concat([
    quotIdent('first_seen_at'), quotIdent('last_synced_at'), quotIdent('is_deleted'),
  ]).join(', ');
  const buchWerte = insertWerte.concat(['now()', 'now()', 'false']).join(', ');

  sql =
    'WITH eingang AS (\n    SELECT t.*' + userRefSelect +
    '\n    FROM jsonb_to_recordset(' + jsonLiteral + ') AS t(' + recordsetDef + ')\n),\n' +
    'kennzahlen AS (\n    SELECT\n        count(*) AS zeilen,\n' +
    '        count(*) FILTER (WHERE o.' + pkQualifiziert + ' IS NULL) AS neu,\n' +
    '        count(*) FILTER (WHERE o.' + pkQualifiziert + ' IS NOT NULL AND ' + hashO + ' IS DISTINCT FROM ' + hashE + ') AS geaendert\n' +
    '    FROM eingang e\n    LEFT JOIN ' + tabelleQualifiziert + ' o ON o.' + pkQualifiziert + ' = e.' + pkQualifiziert + '\n),\n' +
    'geschrieben AS (\n    INSERT INTO ' + tabelleQualifiziert + ' AS o (' + buchInsert + ')\n' +
    '    SELECT ' + buchWerte + '\n    FROM eingang e\n' +
    '    ON CONFLICT (' + pkQualifiziert + ') DO UPDATE SET\n        ' + updateSet.join(',\n        ') + ',\n' +
    '        ' + quotIdent('last_synced_at') + ' = now(),\n' +
    '        ' + quotIdent('is_deleted') + ' = false\n' +
    '    RETURNING o.' + pkQualifiziert + '\n)';
}

// Loesch-Markierung nur im Vollabgleich.
if (loeschungen) {
  sql +=
    ',\nfehlend AS (\n    UPDATE ' + tabelleQualifiziert + '\n' +
    '    SET ' + quotIdent('is_deleted') + ' = true, ' + quotIdent('last_synced_at') + ' = now()\n' +
    '    WHERE ' + quotIdent('is_deleted') + ' = false\n' +
    '      AND ' + pkQualifiziert + ' NOT IN (SELECT ' + pkQualifiziert + ' FROM eingang)\n' +
    '    RETURNING ' + pkQualifiziert + '\n)';
}

sql +=
  '\nSELECT\n' +
  '    (SELECT zeilen FROM kennzahlen) AS gelesen,\n' +
  '    (SELECT neu FROM kennzahlen) AS neu,\n' +
  '    (SELECT geaendert FROM kennzahlen) AS geaendert,\n' +
  '    (SELECT count(*) FROM geschrieben) AS gespeichert' +
  (loeschungen ? ',\n    (SELECT count(*) FROM fehlend) AS geloescht' : '') +
  ';';

return [{
  json: {
    kennung: k.kennung,
    run_id: runId,
    endpunkt: k.endpunkt,
    zieltabelle: k.zieltabelle,
    gemeldet_total: total,
    gelesen: saetze.length,
    abrufe,
    vollstaendig: total !== null ? saetze.length === total : null,
    loeschungen,
    upsertSql: sql,
    datenJson,
  },
}];

// P90 - Zaehlwerte ausgeben
// Fuehrt die Ergebniszahlen aus dem Speichern-Node und dem Holen-Node zusammen.
// Grundlage fuer sync_run und die Qualitaetskontrolle P04.

const speichern = $('P90 Ressource speichern').first().json;
const holen = $('P90 Ressource holen').first().json;

function z(w) {
  const n = Number(w);
  return Number.isFinite(n) ? n : 0;
}

return [{
  json: {
    kennung: holen.kennung,
    run_id: holen.run_id,
    endpunkt: holen.endpunkt,
    zieltabelle: holen.zieltabelle,
    api_aufrufe: z(holen.abrufe),
    gemeldet_total: holen.gemeldet_total !== undefined ? holen.gemeldet_total : null,
    gelesen: z(speichern.gelesen ?? holen.gelesen),
    neu: z(speichern.neu),
    geaendert: z(speichern.geaendert),
    gespeichert: z(speichern.gespeichert),
    geloescht: z(speichern.geloescht),
    vollstaendig: holen.vollstaendig,
  },
}];

// P90 - Fehlertext aufbereiten (Eingang des Fehlerpfads)
// Extrahiert Fehlermeldung und ggf. run_id und uebergibt sie parametrisiert
// (jsonb) an die Fehlerprotokollierung.

const fehler = $input.first().json;
const meldung = fehler.message ?? fehler.error?.message ?? fehler.error ?? 'Unbekannter Fehler in P90';
const rohRunId = fehler.run_id ?? fehler.runId ?? null;
const runId = (rohRunId === null || rohRunId === '' || rohRunId === undefined)
  ? null
  : Number(rohRunId);

const fehlerText = String(meldung).slice(0, 2000);

return [{
  json: {
    fehler_text: fehlerText,
    run_id: runId,
    fehlerJson: JSON.stringify([{ fehler_text: fehlerText, run_id: runId }]),
  },
}];
